from AlgorithmImports import *

class PrivateLotStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_close = {}
        self.previous_spy_sma = None
        self.red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, slice: Slice):
        for symbol in self.symbols:
            if symbol in slice.Bars:
                close = slice.Bars[symbol].Close

                if symbol == self.spy:
                    self.spy_sma.Update(self.Time, close)

                if symbol == self.aapl:
                    self.aapl_rsi.Update(self.Time, close)

                    if symbol in self.previous_close:
                        if close < self.previous_close[symbol]:
                            self.red_streak += 1
                        else:
                            self.red_streak = 0

                self.previous_close[symbol] = close

        if any(symbol not in slice.Bars for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self.previous_spy_sma = self.spy_sma.Current.Value
            return

        if self.previous_spy_sma is None or self.spy not in self.previous_close:
            self.previous_spy_sma = self.spy_sma.Current.Value
            return

        spy_close = slice.Bars[self.spy].Close
        aapl_close = slice.Bars[self.aapl].Close
        spy_sma_today = self.spy_sma.Current.Value
        spy_sma_yesterday = self.previous_spy_sma

        previous_spy_close = self.previous_close[self.spy]
        previous_aapl_close = self.previous_close[self.aapl]

        spy_crossed_below = (
            previous_spy_close >= spy_sma_yesterday and
            spy_close < spy_sma_today
        )

        if self.strategy_a_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        spy_crossed_above = (
            previous_spy_close <= spy_sma_yesterday and
            spy_close > spy_sma_today
        )

        if self.strategy_a_lot == 0 and spy_crossed_above:
            shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_lot = shares

        self.previous_spy_sma = spy_sma_today

