class ParallelSmaRsiStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 50
        self.spy_closes = RollingWindow[float](self.sma_period + 1)
        self.aapl_closes = RollingWindow[float](2)
        self.aapl_red_streak = 0

        self.aapl_rsi = self.rsi(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.set_warm_up(self.sma_period + 1, Resolution.DAILY)

    def on_data(self, data: Slice):
        for symbol in self.symbols.values():
            if symbol not in data.bars:
                continue

            bar = data.bars[symbol]

            if symbol == self.spy:
                self.spy_closes.add(float(bar.close))

            if symbol == self.aapl:
                previous_close = self.aapl_closes[0] if self.aapl_closes.count > 0 else None
                self.aapl_closes.add(float(bar.close))

                if previous_close is None:
                    self.aapl_red_streak = 0
                elif bar.close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        if any(symbol not in data.bars for symbol in self.symbols.values()):
            return

        if self.is_warming_up:
            return

        if self.spy_closes.count < self.sma_period + 1 or not self.aapl_rsi.is_ready:
            return

        spy_close = float(data.bars[self.spy].close)
        aapl_close = float(data.bars[self.aapl].close)

        today_sma = sum(self.spy_closes[i] for i in range(self.sma_period)) / self.sma_period
        yesterday_sma = (
            sum(self.spy_closes[i] for i in range(1, self.sma_period + 1))
            / self.sma_period
        )
        yesterday_spy_close = self.spy_closes[1]

        spy_crosses_above = (
            yesterday_spy_close <= yesterday_sma and spy_close > today_sma
        )
        spy_crosses_below = (
            yesterday_spy_close >= yesterday_sma and spy_close < today_sma
        )

        # Sells before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.market_order(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            shares = int((0.40 * self.portfolio.total_portfolio_value) // spy_close)
            if shares > 0:
                self.market_order(self.spy, shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.market_order(self.aapl, shares)
                    self.strategy_b_lot = shares

