from AlgorithmImports import *


class ParallelStrategiesAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.sma(self.spy, 200, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.previous_closes = {}
        self.previous_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def on_data(self, data: Slice):
        present = all(data.bars.contains_key(symbol) for symbol in self.symbols.values())

        if data.bars.contains_key(self.aapl):
            aapl_close = data.bars[self.aapl].close
            if self.aapl in self.previous_closes:
                if aapl_close < self.previous_closes[self.aapl]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        if not present:
            for ticker, symbol in self.symbols.items():
                if data.bars.contains_key(symbol):
                    self.previous_closes[symbol] = data.bars[symbol].close
            return

        spy_close = data.bars[self.spy].close
        aapl_close = data.bars[self.aapl].close

        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            self.previous_closes[self.spy] = spy_close
            self.previous_closes[self.aapl] = aapl_close
            self.previous_sma = self.spy_sma.current.value if self.spy_sma.is_ready else None
            for ticker, symbol in self.symbols.items():
                if data.bars.contains_key(symbol):
                    self.previous_closes[symbol] = data.bars[symbol].close
            return

        current_sma = self.spy_sma.current.value

        if self.strategy_a_lot > 0:
            if (self.previous_closes.get(self.spy) is not None and
                    self.previous_sma is not None and
                    self.previous_closes[self.spy] >= self.previous_sma and
                    spy_close < current_sma):
                self.market_order(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            if (self.previous_closes.get(self.spy) is not None and
                    self.previous_sma is not None and
                    self.previous_closes[self.spy] <= self.previous_sma and
                    spy_close > current_sma):
                shares = int((self.portfolio.total_portfolio_value * 0.40) / spy_close)
                if shares > 0:
                    self.market_order(self.spy, shares)
                    self.strategy_a_lot = shares

        if self.strategy_b_lot == 0:
            if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                shares = int(20_000 / aapl_close)
                if shares > 0:
                    self.market_order(self.aapl, shares)
                    self.strategy_b_lot = shares

        for ticker, symbol in self.symbols.items():
            self.previous_closes[symbol] = data.bars[symbol].close
        self.previous_sma = current_sma

