class IndependentDailyStrategies(QCAlgorithm):

    MA_PERIOD = 50

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, self.MA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.sma_values = RollingWindow[IndicatorDataPoint](2)
        self.rsi_values = RollingWindow[IndicatorDataPoint](2)
        self.spy_sma.Updated += lambda sender, point: self.sma_values.Add(point)
        self.aapl_rsi.Updated += lambda sender, point: self.rsi_values.Add(point)

        self.close_windows = {
            symbol: RollingWindow[float](2)
            for symbol in self.symbols.values()
        }
        self.red_streaks = {
            symbol: 0
            for symbol in self.symbols.values()
        }

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.SetWarmUp(self.MA_PERIOD + 1, Resolution.Daily)

    def OnData(self, data: Slice):
        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                continue

            close = float(data.Bars[symbol].Close)
            closes = self.close_windows[symbol]

            if closes.Count > 0:
                if close < closes[0]:
                    self.red_streaks[symbol] += 1
                else:
                    self.red_streaks[symbol] = 0

            closes.Add(close)

        if self.IsWarmingUp:
            return

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if (not self.spy_sma.IsReady or
                not self.aapl_rsi.IsReady or
                self.sma_values.Count < 2 or
                self.rsi_values.Count < 2 or
                self.close_windows[self.spy].Count < 2 or
                self.close_windows[self.aapl].Count < 2):
            return

        spy_close = self.close_windows[self.spy][0]
        spy_previous_close = self.close_windows[self.spy][1]
        sma_today = float(self.sma_values[0].Value)
        sma_yesterday = float(self.sma_values[1].Value)
        rsi_today = float(self.rsi_values[0].Value)
        aapl_close = self.close_windows[self.aapl][0]

