            if aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if (
            self.previous_spy_close is not None
            and self.previous_spy_ma is not None
            and spy_ma_ready
            and rsi_ready
        ):
            current_spy_ma = self.spy_ma.Current.Value
            current_rsi = self.aapl_rsi.Current.Value

            # Sells before buys.
            if (
                self.lots["StrategyA"] > 0
                and self.previous_spy_close >= self.previous_spy_ma
                and spy_close < current_spy_ma
            ):
                self.MarketOrder(self.spy, -self.lots["StrategyA"], tag="StrategyA")

            if self.lots["StrategyB"] > 0 and current_rsi > 60:
                self.MarketOrder(self.aapl, -self.lots["StrategyB"], tag="StrategyB")

            if (
                self.lots["StrategyA"] == 0
                and self.previous_spy_close <= self.previous_spy_ma
                and spy_close > current_spy_ma
            ):
                quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity, tag="StrategyA")

            if (
                self.lots["StrategyB"] == 0
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity, tag="StrategyB")

        if spy_ma_ready:
            self.previous_spy_ma = self.spy_ma.Current.Value

        self.previous_spy_close = spy_close
        self.previous_aapl_close = aapl_close

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag == "StrategyA":
            self.lots["StrategyA"] += order_event.FillQuantity
        elif order.Tag == "StrategyB":
            self.lots["StrategyB"] += order_event.FillQuantity

