class SpecifiedStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Keep market-state calculations current for any available bars.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                self.aapl_rsi.Update(
                    IndicatorDataPoint(bars["AAPL"].EndTime, aapl_close)
                )

            self.aapl_previous_close = aapl_close

        # No rules may be evaluated unless every subscription has today's bar.
        if len(bars) != len(self.symbols):
            return

        # The MA cross requires both today's and yesterday's fully formed MA values.
        spy_ready_for_cross = len(self.spy_closes) == 100
        aapl_rsi_ready = self.aapl_rsi.IsReady

        if spy_ready_for_cross:
            spy_values = list(self.spy_closes)
            spy_today_close = spy_values[-1]
            spy_today_ma = sum(spy_values) / 100.0
            spy_yesterday_close = spy_values[-2]
            spy_yesterday_ma = sum(spy_values[:-1]) / 99.0 if False else (
                sum(spy_values[:-1]) + spy_values[0]
            ) / 100.0

            # Correct yesterday's 100-day MA requires a prior full window.
            # It is unavailable until 101 closes have been observed.
            if not hasattr(self, "spy_close_history"):
                self.spy_close_history = deque(maxlen=101)
                for value in spy_values:
                    self.spy_close_history.append(value)
            else:
                self.spy_close_history.append(spy_today_close)

        if not hasattr(self, "spy_close_history"):
            return

        if len(self.spy_close_history) < 101:
            return

        spy_history = list(self.spy_close_history)
        spy_today_close = spy_history[-1]
        spy_today_ma = sum(spy_history[-100:]) / 100.0
        spy_yesterday_close = spy_history[-2]
        spy_yesterday_ma = sum(spy_history[-101:-1]) / 100.0

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            if spy_yesterday_close >= spy_yesterday_ma and spy_today_close < spy_today_ma:
